void deterministic_random_bytes(void *buf, size_t len) {
  for (int i = 0; i < len; i++) {
    ((uint8_t *)buf)[i] = 0;
  }
}

static int fake_ticket_cb(ptls_save_ticket_t *_self, ptls_t *tls,
